/* The C text code that runtime.c used before it moved to Rust
   (runtime/chimi-runtime/src/text.rs and graphemes.rs, CHI-307), kept as the
   oracle for differential fuzzing: the text target checks that both trim, map
   case and split graphemes the same way. Its tables are a frozen Unicode 17.0.0
   copy that tests/unicode_tables.rs no longer regenerates, so a Unicode update
   that changes the Rust side will show up here as a difference to review. It is
   included after runtime.c and uses its TextBuffer and value constructors; the
   code is the shipped code with its names prefixed. */

/* Unicode White_Space, the characters Text.trim_start and Text.trim_end remove; the
   Rust side's chimi_runtime::text::is_white_space keeps the same table. */
/* Whether `offset` starts a UTF-8 sequence of `text` or is its end, as
   runtime.c's utf8_boundary was. */
static bool reference_utf8_boundary(const char *text, size_t length, size_t offset) {
  return offset == length || ((unsigned char)text[offset] & 0xc0) != 0x80;
}
static bool reference_is_white_space(uint32_t code) {
  return (code >= 0x9 && code <= 0xd) || code == 0x20 || code == 0x85 || code == 0xa0 ||
         code == 0x1680 || (code >= 0x2000 && code <= 0x200a) || code == 0x2028 ||
         code == 0x2029 || code == 0x202f || code == 0x205f || code == 0x3000;
}
/* Decodes the valid UTF-8 sequence at `text`, storing its length in `length`. */
static uint32_t reference_utf8_decode(const unsigned char *text, size_t *length) {
  if (text[0] < 0x80) { *length = 1; return text[0]; }
  if (text[0] < 0xe0) { *length = 2; return ((uint32_t)(text[0] & 0x1f) << 6) | (text[1] & 0x3f); }
  if (text[0] < 0xf0) {
    *length = 3;
    return ((uint32_t)(text[0] & 0x0f) << 12) | ((uint32_t)(text[1] & 0x3f) << 6) | (text[2] & 0x3f);
  }
  *length = 4;
  return ((uint32_t)(text[0] & 0x07) << 18) | ((uint32_t)(text[1] & 0x3f) << 12) |
         ((uint32_t)(text[2] & 0x3f) << 6) | (text[3] & 0x3f);
}
