/* end of the frozen copy of the generated unicode case tables */
#define REFERENCE_CAPITAL_SIGMA 0x3a3
#define REFERENCE_SMALL_SIGMA 0x3c3
#define REFERENCE_SMALL_FINAL_SIGMA 0x3c2
static const ReferenceCaseMapping *reference_find_case_mapping(const ReferenceCaseMapping *table, size_t count, uint32_t code) {
  size_t low = 0, high = count;
  while (low < high) {
    size_t middle = low + (high - low) / 2;
    if (table[middle].code < code) low = middle + 1; else high = middle;
  }
  return low < count && table[low].code == code ? &table[low] : NULL;
}
static uint8_t reference_sigma_context(uint32_t code) {
  size_t low = 0, high = COUNT_OF(reference_sigma_context_ranges);
  while (low < high) {
    size_t middle = low + (high - low) / 2;
    if (reference_sigma_context_ranges[middle].last < code) low = middle + 1; else high = middle;
  }
  if (low < COUNT_OF(reference_sigma_context_ranges) && reference_sigma_context_ranges[low].first <= code)
    return reference_sigma_context_ranges[low].context;
  return REFERENCE_SIGMA_CONTEXT_OTHER;
}
/* Final_Sigma as Rust tests it: skip Case_Ignorable characters, then ask whether the
   next character is Cased. `before` scans backwards from `offset`, otherwise forwards. */
static bool reference_cased_beyond_ignorables(const char *text, size_t length, size_t offset, bool before) {
  size_t width;
  while (before ? offset > 0 : offset < length) {
    size_t start = offset;
    if (before) { start = offset - 1; while (start > 0 && !reference_utf8_boundary(text, length, start)) --start; }
    uint8_t context = reference_sigma_context(reference_utf8_decode((const unsigned char *)text + start, &width));
    if (context != REFERENCE_SIGMA_CONTEXT_IGNORABLE) return context == REFERENCE_SIGMA_CONTEXT_CASED;
    offset = before ? start : start + width;
  }
  return false;
}
static ChimiValue *reference_text_case_map(const ChimiValue *value, const ReferenceCaseMapping *table, size_t count,
                                 bool final_sigma) {
  const char *text = value->as.text.bytes;
  size_t length = value->as.text.length;
  TextBuffer buffer = {0};
  for (size_t offset = 0, width; offset < length; offset += width) {
    uint32_t code = reference_utf8_decode((const unsigned char *)text + offset, &width);
    if (final_sigma && code == REFERENCE_CAPITAL_SIGMA) {
      bool is_final = reference_cased_beyond_ignorables(text, length, offset, true) &&
                      !reference_cased_beyond_ignorables(text, length, offset + width, false);
      buffer_utf8(&buffer, is_final ? REFERENCE_SMALL_FINAL_SIGMA : REFERENCE_SMALL_SIGMA);
      continue;
    }
    const ReferenceCaseMapping *mapping = reference_find_case_mapping(table, count, code);
    if (!mapping) { buffer_bytes(&buffer, text + offset, width); continue; }
    for (int i = 0; i < 3 && mapping->mapped[i]; ++i) buffer_utf8(&buffer, mapping->mapped[i]);
  }
  return buffer.data ? text_from_bytes(buffer.data, buffer.length) : text_value("");
}

