/* end of the frozen copy of the generated grapheme table */
static ReferenceGraphemeRange reference_grapheme_properties(uint32_t code) {
  size_t low = 0, high = COUNT_OF(reference_grapheme_ranges);
  while (low < high) {
    size_t middle = low + (high - low) / 2;
    if (reference_grapheme_ranges[middle].last < code) low = middle + 1; else high = middle;
  }
  if (low < COUNT_OF(reference_grapheme_ranges) && reference_grapheme_ranges[low].first <= code) return reference_grapheme_ranges[low];
  return (ReferenceGraphemeRange){code, code, REFERENCE_GB_OTHER, REFERENCE_INCB_NONE, 0};
}
/* How far a cluster has matched the GB9c sequence Consonant [Extend Linker]* Linker
   [Extend Linker]*. */
enum { REFERENCE_CONJUNCT_RUN_NONE, REFERENCE_CONJUNCT_RUN_CONSONANT, REFERENCE_CONJUNCT_RUN_LINKED };
/* What the rules need to know about the cluster read so far. */
typedef struct {
  uint8_t previous, conjunct_run;
  bool pictographic_run;        /* ends in Extended_Pictographic Extend* (GB11) */
  bool pictographic_joiner;     /* ends in Extended_Pictographic Extend* ZWJ (GB11) */
  bool odd_regional_indicators; /* ends in an odd number of regional indicators (GB12, GB13) */
} ReferenceGraphemeCluster;
/* The rules GB3 to GB999, in their order of precedence. */
static bool reference_grapheme_breaks_before(const ReferenceGraphemeCluster *cluster, ReferenceGraphemeRange next) {
  uint8_t previous = cluster->previous, current = next.grapheme_break;
  if (previous == REFERENCE_GB_CR && current == REFERENCE_GB_LF) return false;
  if (previous == REFERENCE_GB_CR || previous == REFERENCE_GB_LF || previous == REFERENCE_GB_CONTROL) return true;
  if (current == REFERENCE_GB_CR || current == REFERENCE_GB_LF || current == REFERENCE_GB_CONTROL) return true;
  if (previous == REFERENCE_GB_L && (current == REFERENCE_GB_L || current == REFERENCE_GB_V || current == REFERENCE_GB_LV || current == REFERENCE_GB_LVT)) return false;
  if ((previous == REFERENCE_GB_LV || previous == REFERENCE_GB_V) && (current == REFERENCE_GB_V || current == REFERENCE_GB_T)) return false;
  if ((previous == REFERENCE_GB_LVT || previous == REFERENCE_GB_T) && current == REFERENCE_GB_T) return false;
  if (current == REFERENCE_GB_EXTEND || current == REFERENCE_GB_ZWJ || current == REFERENCE_GB_SPACING_MARK || previous == REFERENCE_GB_PREPEND) return false;
  if (cluster->conjunct_run == REFERENCE_CONJUNCT_RUN_LINKED && next.conjunct == REFERENCE_INCB_CONSONANT) return false;
  if (previous == REFERENCE_GB_ZWJ && cluster->pictographic_joiner && next.pictographic) return false;
  if (previous == REFERENCE_GB_REGIONAL_INDICATOR && current == REFERENCE_GB_REGIONAL_INDICATOR) return !cluster->odd_regional_indicators;
  return true;
}
static void reference_grapheme_extend(ReferenceGraphemeCluster *cluster, ReferenceGraphemeRange next) {
  cluster->pictographic_joiner = next.grapheme_break == REFERENCE_GB_ZWJ && cluster->pictographic_run;
  cluster->pictographic_run = next.pictographic || (cluster->pictographic_run && next.grapheme_break == REFERENCE_GB_EXTEND);
  cluster->odd_regional_indicators =
      next.grapheme_break == REFERENCE_GB_REGIONAL_INDICATOR && !cluster->odd_regional_indicators;
  if (next.conjunct == REFERENCE_INCB_CONSONANT) cluster->conjunct_run = REFERENCE_CONJUNCT_RUN_CONSONANT;
  else if (cluster->conjunct_run == REFERENCE_CONJUNCT_RUN_NONE) cluster->conjunct_run = REFERENCE_CONJUNCT_RUN_NONE;
  else if (next.conjunct == REFERENCE_INCB_LINKER) cluster->conjunct_run = REFERENCE_CONJUNCT_RUN_LINKED;
  else if (next.conjunct != REFERENCE_INCB_EXTEND) cluster->conjunct_run = REFERENCE_CONJUNCT_RUN_NONE;
  cluster->previous = next.grapheme_break;
}
/* Returns the byte offset where the cluster that starts at the character boundary
   `start` ends, or `length` when `start` is the end. */
static size_t reference_grapheme_end(const char *text, size_t length, size_t start) {
  if (start == length) return start;
  size_t width;
  ReferenceGraphemeRange first = reference_grapheme_properties(reference_utf8_decode((const unsigned char *)text + start, &width));
  ReferenceGraphemeCluster cluster = {
    first.grapheme_break,
    first.conjunct == REFERENCE_INCB_CONSONANT ? REFERENCE_CONJUNCT_RUN_CONSONANT : REFERENCE_CONJUNCT_RUN_NONE,
    first.pictographic, false, first.grapheme_break == REFERENCE_GB_REGIONAL_INDICATOR,
  };
  for (size_t offset = start + width; offset < length; offset += width) {
    ReferenceGraphemeRange next = reference_grapheme_properties(reference_utf8_decode((const unsigned char *)text + offset, &width));
    if (reference_grapheme_breaks_before(&cluster, next)) return offset;
    reference_grapheme_extend(&cluster, next);
  }
  return length;
}


/* Text.trim_start and Text.trim_end as invoke_core_operation spelled them. */
static ChimiValue *reference_text_trim(const ChimiValue *value, bool trim_end) {
  if (!trim_end) {
    const unsigned char *text = (const unsigned char *)value->as.text.bytes;
    const unsigned char *end = text + value->as.text.length;
    size_t width;
    while (text < end && reference_is_white_space(reference_utf8_decode(text, &width))) text += width;
    return text_from_bytes((const char *)text, (size_t)(end - text));
  }
  const char *text = value->as.text.bytes;
  size_t end = value->as.text.length, width;
  while (end > 0) {
    size_t start = end - 1;
    while (start > 0 && !reference_utf8_boundary(text, end, start)) --start;
    if (!reference_is_white_space(reference_utf8_decode((const unsigned char *)text + start, &width))) break;
    end = start;
  }
  return text_from_bytes(text, end);
}
/* The reference's value for map `index` of fuzz_text: lower, upper, trim_start, trim_end. */
static ChimiValue *reference_text_map(size_t index, const ChimiValue *text) {
  switch (index) {
    case 0: return reference_text_case_map(text, reference_lowercase_mappings, COUNT_OF(reference_lowercase_mappings), true);
    case 1: return reference_text_case_map(text, reference_uppercase_mappings, COUNT_OF(reference_uppercase_mappings), false);
    default: return reference_text_trim(text, index == 3);
  }
}
